import sys


def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    state = {}
    order = []
    pos = 1
    for _ in range(n):
        name = data[pos]
        verdict = data[pos + 1]
        pos += 2
        cur = state.get(name)
        if cur is None:
            cur = [0, 0]
            state[name] = cur
            order.append(name)
        if cur[1] != 0:
            continue
        if verdict == b"Accepted":
            cur[1] = 1
        else:
            cur[0] += 1
            if cur[0] == 4:
                cur[1] = 2
    words = ("open", "sealed", "broken")
    out = []
    for name in order:
        out.append(name.decode() + " " + words[state[name][1]])
    sys.stdout.write("\n".join(out) + "\n")


main()
